mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  p.yz = rot(0.5) * p.yz;
  float ring = length(vec2(length(p.xz) - 1.5, p.y)) - 0.15;
  float star = length(p) - (0.5 + 0.1 * sin(time * 4.0) * bass);
  return min(ring, star);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.5);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.01, 0.04);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(0.0, 1.0, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    float isStar = step(length(pos), 0.7);
    vec3 starCol = vec3(1.2, 0.6, 0.1) * 2.0;
    vec3 forgeCol = vec3(0.08, 0.05, 0.12) + diff * vec3(0.4, 0.2, 0.6) + spec * vec3(0.9, 0.8, 1.0);
    col = mix(forgeCol, starCol, isStar);
  }
  ret = col;
}
